with base as (select id, order_id, carrier, shipped_date, delivered_date, cost, status, last_day(delivered_date) as delivered_date_month_end, cast(cost as int) as cost_int, coalesce(carrier, 'NONE') as resolved_carrier from shipments where shipped_date > date '2023-06-16' and carrier is not null) select * from (select status, carrier, cost from base) src pivot (max(cost) as total for carrier in ('FedEx' as fedex, 'Flash' as flash, 'DHL' as dhl))
